package parser

// This file implements Unicode whitespace and punctuation classification
// aligned with md4c's WHITESPACE_MAP and PUNCT_MAP (md4c.c:607-707).
//
// md4c uses auto-generated lookup tables from Unicode P+S categories for
// punctuation and Zs category for whitespace. Go's unicode.Zs matches
// WHITESPACE_MAP exactly, but Go's unicode.IsPunct+IsSymbol has ~59
// differences in supplementary planes (emoji, rare scripts) compared to
// md4c's PUNCT_MAP.
//
// For full alignment, we implement our own punctuation lookup using md4c's
// exact PUNCT_MAP with binary search.

// isMd4cUnicodeWhitespace checks if a codepoint (>0x7F) is Unicode whitespace.
// Mirrors md4c md_is_unicode_whitespace__() (md4c.c:607-625).
// Go's unicode.Zs matches md4c's WHITESPACE_MAP exactly.
func isMd4cUnicodeWhitespace(cp rune) bool {
	return unicodeIsZs(cp)
}

// unicodeIsZs checks if a rune is in Unicode Zs category (whitespace).
// This is equivalent to unicode.Is(unicode.Zs, r) but inlined for performance.
func unicodeIsZs(r rune) bool {
	// md4c WHITESPACE_MAP (md4c.c:614):
	//   S(0x0020), S(0x00a0), S(0x1680), R(0x2000,0x200a),
	//   S(0x202f), S(0x205f), S(0x3000)
	switch {
	case r == 0x0020 || r == 0x00A0 || r == 0x1680:
		return true
	case r >= 0x2000 && r <= 0x200A:
		return true
	case r == 0x202F || r == 0x205F || r == 0x3000:
		return true
	}
	return false
}

// isMd4cUnicodePunct checks if a codepoint (>0x7F) is Unicode punctuation.
// Mirrors md4c md_is_unicode_punct__() (md4c.c:628-707).
// Uses md4c's exact PUNCT_MAP for full alignment.
func isMd4cUnicodePunct(cp rune) bool {
	return md4cPunctLookup(cp)
}

// md4cPunctRange represents a range in md4c's PUNCT_MAP.
type md4cPunctRange struct {
	lo, hi rune
}

