// md4cPunctLookup performs binary search in md4c's PUNCT_MAP.
// Mirrors md4c md_unicode_bsearch__() (md4c.c:544-564).
func md4cPunctLookup(cp rune) bool {
	var table []md4cPunctRange
	if cp <= 0xFFFF {
		table = md4cPunctBMP
	} else {
		table = md4cPunctSMP
	}
	lo, hi := 0, len(table)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		r := table[mid]
		if cp < r.lo {
			hi = mid - 1
		} else if cp > r.hi {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}
